{
	"name": "opencode-zoekt-code-search",
	"version": "0.2.1",
	"description": "OpenCode plugin that keeps a Zoekt code-search index fresh in the background.",
	"license": "MIT",
	"type": "module",
	"main": "dist/index.js",
	"types": "dist/index.d.ts",
	"exports": {
		".": "./dist/index.js",
		"./server": "./dist/index.js"
	},
	"files": [
		"dist",
		"README.md",
		"LICENSE"
	],
	"engines": {
		"node": ">=18",
		"opencode": ">=1.0.0"
	},
	"scripts": {
		"clean": "rm -rf dist",
		"build": "bun run clean && bun build src/index.ts --outfile dist/index.js --target node --external @opencode-ai/plugin && bun build src/index.ts --outfile dist/standalone.js --target node && tsc -p tsconfig.build.json",
		"typecheck": "tsc --noEmit",
		"test": "bun test",
		"prepack": "bun run build"
	},
	"keywords": [
		"opencode",
		"opencode-plugin",
		"zoekt",
		"code-search"
	],
	"peerDependencies": {
		"@opencode-ai/plugin": ">=1.0.0"
	},
	"devDependencies": {
		"@opencode-ai/plugin": "^1.14.50",
		"@types/bun": "^1.3.14",
		"@types/node": "^22.19.19",
		"typescript": "^5.9.3"
	}
}
